#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

const int64 MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string start, target;
    int k;
    cin >> start >> target >> k;

    const int n = static_cast<int>(start.size());
    const string doubled = start + start;

    int matchingRotations = 0;
    for (int i = 0; i < n; ++i) {
        if (doubled.compare(i, n, target) == 0) {
            ++matchingRotations;
        }
    }

    int64 good = (start == target);
    int64 bad = 1 - good;

    for (int step = 0; step < k; ++step) {
        int64 nextGood =
            (good * (matchingRotations - 1) +
             bad * matchingRotations) % MOD;

        int64 nextBad =
            (good * (n - matchingRotations) +
             bad * (n - matchingRotations - 1)) % MOD;

        good = (nextGood + MOD) % MOD;
        bad = (nextBad + MOD) % MOD;
    }

    cout << good << '\n';
    return 0;
}

