#include <iostream>
#include <string>
#include <vector>

using namespace std;

using int64 = long long;

constexpr int64 MOD = 1000000007LL;

struct Matrix {
    int64 a[2][2] = {};
};

Matrix multiply(const Matrix& x, const Matrix& y) {
    Matrix result;
    for (int i = 0; i < 2; ++i) {
        for (int k = 0; k < 2; ++k) {
            for (int j = 0; j < 2; ++j) {
                result.a[i][j] =
                    (result.a[i][j] + x.a[i][k] * y.a[k][j]) % MOD;
            }
        }
    }
    return result;
}

Matrix power(Matrix base, long long exponent) {
    Matrix result;
    result.a[0][0] = result.a[1][1] = 1;

    while (exponent > 0) {
        if (exponent & 1LL) {
            result = multiply(result, base);
        }
        base = multiply(base, base);
        exponent >>= 1LL;
    }
    return result;
}

int countMatchingRotations(const string& start, const string& target) {
    const int n = static_cast<int>(start.size());
    vector<int> prefix(n);

    for (int i = 1, j = 0; i < n; ++i) {
        while (j > 0 && target[i] != target[j]) {
            j = prefix[j - 1];
        }
        if (target[i] == target[j]) {
            ++j;
        }
        prefix[i] = j;
    }

    const string text = start + start;
    int matches = 0;

    for (int i = 0, j = 0; i < static_cast<int>(text.size()); ++i) {
        while (j > 0 && text[i] != target[j]) {
            j = prefix[j - 1];
        }
        if (text[i] == target[j]) {
            ++j;
        }

        if (j == n) {
            const int position = i - n + 1;
            if (position < n) {
                ++matches;
            }
            j = prefix[j - 1];
        }
    }

    return matches;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string start, target;
    long long k;

    if (!(cin >> start >> target >> k)) {
        return 0;
    }

    if (start.size() != target.size() || start.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    const int64 n = static_cast<int64>(start.size());
    const int64 matchingRotations = countMatchingRotations(start, target);

    Matrix transition;
    transition.a[0][0] = (matchingRotations - 1 + MOD) % MOD;
    transition.a[0][1] = (n - matchingRotations) % MOD;
    transition.a[1][0] = matchingRotations % MOD;
    transition.a[1][1] = (n - matchingRotations - 1 + MOD) % MOD;

    const Matrix result = power(transition, k);
    const bool initiallyMatching = (start == target);

    cout << result.a[initiallyMatching ? 0 : 1][0] << '\n';
    return 0;
}

