    Matrix result;
    result.a[0][0] = result.a[1][1] = 1;

    while (exponent > 0) {
        if (exponent & 1LL) {
            result = multiply(result, base);
        }
        base = multiply(base, base);
        exponent >>= 1LL;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string start, target;
    long long k;

    if (!(cin >> start >> target >> k) || start.size() != target.size()) {
        cout << 0 << '\n';
        return 0;
    }

    const int n = static_cast<int>(start.size());

    if (n == 0) {
        cout << (k == 0 ? 1 : 0) << '\n';
        return 0;
    }

    vector<int> prefix(n);
    for (int i = 1, j = 0; i < n; ++i) {
        while (j > 0 && target[i] != target[j]) {
            j = prefix[j - 1];
        }
        if (target[i] == target[j]) {
            ++j;
        }
        prefix[i] = j;
    }

    string doubled = start + start;
    int matches = 0;

    for (int i = 0, j = 0; i < 2 * n - 1; ++i) {
        while (j > 0 && doubled[i] != target[j]) {
            j = prefix[j - 1];
        }
        if (doubled[i] == target[j]) {
            ++j;
        }
        if (j == n) {
            ++matches;
            j = prefix[j - 1];
        }
    }

    if (matches == 0) {
        cout << 0 << '\n';
        return 0;
    }

    if (n == 1) {
        cout << ((k == 0 && start == target) ? 1 : 0) << '\n';
        return 0;
    }

    Matrix transition;
    transition.a[0][0] = 0;
    transition.a[0][1] = n - 1;
    transition.a[1][0] = 1;
    transition.a[1][1] = n - 2;

    Matrix result = power(transition, k);
    const int64 sameRotationWays = result.a[0][0];
    const int64 otherRotationWays = result.a[1][0];

    int64 answer;
    if (start == target) {
        answer = (sameRotationWays +
                  static_cast<int64>(matches - 1) * otherRotationWays) % MOD;
    } else {
        answer = static_cast<int64>(matches) * otherRotationWays % MOD;
    }

    cout << answer << '\n';
    return 0;
}

